int prime(int n)
{
bool flag = true;
for (int i = 2; i < n; i ++ )
{
if (n % i == 0)
{
int j;
for (j = 2; j < i; j ++ ) if (i % j == 0) break;
if (j != i)
{
flag = 0;
continue;
}
return i;
}
}
return flag == 1 ? n : 0;
}

