dp[1] = a[1];
for (int i = 1; i < n; i++)
{
int d = prime(n - i);
for (int j = 1; j <= d; j ++ )
{
if (i + j > n) break;
dp[i + j] = max(dp[i + j], dp[i] + a[j + i]);
}
}
cout << dp[n] << endl;

